        throw std::runtime_error(std::string(__FILE__ ":") + std::to_string(__LINE__) +            \
                                 " in function " + __func__ + ": " + x);                           \
    } while (false)

inline void check_cublas_(cublasStatus_t status) {
    if ( status != CUBLAS_STATUS_SUCCESS ) {
        CUDA_ERROR("CUBLAS Error: " + std::string(cublasGetStatusString(status)));
    }
}

#define CUDA_CHECK_CUBLAS(ans) { check_cublas_(ans); }

// Vector saves m, n, k, a_t, b_t
std::vector<std::tuple<int, int, int, bool, bool>> inference_server_set = {
    // gemm
    std::make_tuple(4096, 1024, 4096, false, true),
    std::make_tuple(4096, 4096, 4096, false, true),
    std::make_tuple(4096, 14336, 4096, false, true),
    std::make_tuple(4096, 4096, 14336, false, true),
    std::make_tuple(8192, 1024, 4096, false, true),
    std::make_tuple(8192, 4096, 4096, false, true),
    std::make_tuple(8192, 14336, 4096, false, true),
    std::make_tuple(8192, 4096, 14336, false, true),
    std::make_tuple(4096, 1024, 8192, false, true),
    std::make_tuple(4096, 8192, 8192, false, true),
    std::make_tuple(4096, 28672, 8192, false, true),
    std::make_tuple(4096, 8192, 28672, false, true),
    std::make_tuple(8192, 1024, 8192, false, true),
    std::make_tuple(8192, 8192, 8192, false, true),
